// The golden corpus: every `test/cases/*.json` case is `{ name, dql, options?,
// oqx, render, warnings }` or `{ name, dql, options?, error }`. The expected
// values were generated by the translator and reviewed as code
// (`DATAVIEW_CASES_UPDATE=1 node --test test/cases.test.ts` regenerates them;
// review the diff). Every successful case is also parsed whole by
// `@omgbase/oqx` and must satisfy the printer's round-trip law — the output is
// OQX the 0.25 engine accepts (`group by` / `having` since 0.24, `flatten`
// since 0.25).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parse, print, stripSpans } from "@omgbase/oqx";
import { DqlError, translate, type TranslateOptions, type Translation } from "../src/index.ts";

interface CaseOptions extends Omit<TranslateOptions, "resolveLink"> {
  /** A fixed link table standing in for the vault. */
  links?: Record<string, string>;
}

interface ErrorShape {
  code: "parse" | "unsupported";
  construct: string | null;
  message: string;
  line: number;
  column: number;
}

interface Case {
  name: string;
  dql: string;
  options?: CaseOptions;
  oqx?: string;
  render?: Translation["render"];
  warnings?: string[];
  error?: ErrorShape;
}

const DIR = new URL("./cases/", import.meta.url).pathname;
const UPDATE = process.env.DATAVIEW_CASES_UPDATE === "1";

function optionsOf(c: Case): TranslateOptions {
  const { links, ...rest } = c.options ?? {};
  const opts: TranslateOptions = { ...rest };
  if (links) opts.resolveLink = (t) => links[t] ?? null;
  return opts;
}

function run(c: Case): { ok: Translation } | { error: ErrorShape } {
  try {
    return { ok: translate(c.dql, optionsOf(c)) };
  } catch (e) {
    if (!(e instanceof DqlError)) throw e;
    return { error: { code: e.code, construct: e.construct, message: e.message, line: e.position?.line ?? 0, column: e.position?.column ?? 0 } };
  }
}

const files = readdirSync(DIR).filter((f) => f.endsWith(".json")).sort();
let total = 0;

for (const file of files) {
  const path = join(DIR, file);
  const cases: Case[] = JSON.parse(readFileSync(path, "utf8"));
  if (UPDATE) {
    for (const c of cases) {
      const r = run(c);
      delete c.oqx; delete c.render; delete c.warnings; delete c.error;
      if ("ok" in r) { c.oqx = r.ok.oqx; c.render = r.ok.render; c.warnings = r.ok.warnings; }
      else c.error = r.error;
    }
    writeFileSync(path, JSON.stringify(cases, null, 2) + "\n");
  }
  for (const c of cases) {
    total++;
    test(`${file.replace(/\.json$/, "")}::${c.name}`, () => {
      const r = run(c);
      if (c.error) {
        assert.ok("error" in r, `expected an error, got ${JSON.stringify("ok" in r ? r.ok.oqx : null)}`);
        assert.deepEqual(r.error, c.error);
        return;
      }
      assert.ok("ok" in r, `unexpected error: ${"error" in r ? r.error.message : ""}`);
      assert.equal(r.ok.oqx, c.oqx);
      assert.deepEqual(r.ok.render, c.render);
      assert.deepEqual(r.ok.warnings, c.warnings ?? []);
      // Every translation is OQX the engine accepts (spec/oqx 0.25: grouping
      // and flatten included), and the printer's round-trip law holds over it.
      const tree = parse(r.ok.oqx);
      assert.deepEqual(stripSpans(parse(print(tree))), stripSpans(tree));
    });
  }
}

test("the corpus is large enough to mean something", () => {
  assert.ok(total >= 60, `${total} cases`);
});
